const $=id=>document.getElementById(id);
const panel=document.createElement('details');panel.id='oauth-panel';panel.innerHTML=`<summary>OAuth connections <span>· login & automatic refresh</span></summary>
<p id="oauth-status" role="status">Checking your private connection…</p><a id="oauth-signin" target="_top" href="/signin-with-chatgpt?return_to=%2Fapi-lab.html" hidden>Sign in to ReleaseRadar to connect an API account ↗</a>
<label class="consent"><input type="checkbox" id="use-oauth" disabled> Use my OAuth connection for this request (hosted relay only)</label>
<div class="action-row"><button type="button" id="oauth-refresh" disabled>Refresh now</button><button type="button" id="oauth-disconnect" disabled>Disconnect</button></div>
<p class="fine">One active connection per tester. Tokens refresh before expiry when sending requests. Disconnect deletes this site's saved tokens; revoke access at the provider to end its grant.</p>
<label for="oauth-provider">Provider preset</label><select id="oauth-provider"><option value="google">Google</option><option value="microsoft">Microsoft Entra ID</option><option value="auth0">Auth0</option><option value="okta">Okta</option><option value="github">GitHub</option><option value="custom">Custom OAuth 2.0 / OIDC</option></select>
<label for="oauth-domain">Tenant or issuer origin (Microsoft tenant ID; Auth0/Okta HTTPS origin)</label><input id="oauth-domain" placeholder="For example: https://your-tenant.auth0.com"><button type="button" id="oauth-preset">Apply provider preset</button>
<p id="oauth-provider-note" class="fine"></p><label for="oauth-client">Registered application client ID</label><input id="oauth-client" autocomplete="off" placeholder="From your provider's app registration">
<label for="oauth-authorization">Authorization endpoint</label><input id="oauth-authorization" type="url"><label for="oauth-token">Token endpoint</label><input id="oauth-token" type="url">
<label for="oauth-scopes">Scopes (space separated)</label><input id="oauth-scopes"><label for="oauth-api-origin">Allowed API origin</label><input id="oauth-api-origin" type="url" placeholder="https://api.example.com"><p class="fine">The token is sent only to this exact origin. No wildcard domains or automatic redirects.</p>
<label for="oauth-auth-method">Client authentication at token endpoint</label><select id="oauth-auth-method"><option value="none">Public client · PKCE, no secret</option><option value="post">Confidential client · secret in POST body</option><option value="basic">Confidential client · HTTP Basic</option></select>
<label for="oauth-secret">Client secret (only for confidential clients)</label><input id="oauth-secret" type="password" autocomplete="new-password" placeholder="Optional; sent over HTTPS and encrypted server-side">
<label for="oauth-extra">Extra authorization parameters (JSON)</label><textarea id="oauth-extra" rows="3">{}</textarea><p class="fine">Allowed: audience, resource, access_type, prompt, include_granted_scopes.</p>
<label for="oauth-callback">Register this exact redirect / callback URL with your provider</label><input id="oauth-callback" readonly><p class="fine">Use Authorization Code grant with PKCE S256. This is a server-side flow; use a web/confidential app when your provider requires a secret. Enable refresh tokens/offline access in the provider settings. ID tokens are not used to sign you into ReleaseRadar.</p>
<button type="button" class="primary" id="oauth-connect" disabled>Connect with provider ↗</button><p class="fine">You will leave this page for provider consent. Unsaved request edits are not retained. Application secrets and tokens are not included in collection exports or browser storage.</p>`;
$('transport').before(panel);
let signedIn=false;
function preset(){const provider=$('oauth-provider').value;let domain=$('oauth-domain').value.trim().replace(/\/$/,'');let auth='',token='',scopes='',origin='',method='none',extra={},note='Register your application and review these settings.';
 if(provider==='google'){auth='https://accounts.google.com/o/oauth2/v2/auth';token='https://oauth2.googleapis.com/token';scopes='openid email profile';origin='https://www.googleapis.com';method='post';extra={access_type:'offline',prompt:'consent'};note='Google web clients require a client secret. Add the API-specific scopes you need; offline access requests a refresh token.';}
 if(provider==='microsoft'){const tenant=domain||'common';if(!/^[a-zA-Z0-9.-]+$/.test(tenant))throw Error('Enter a Microsoft tenant ID or common, not a URL.');auth=`https://login.microsoftonline.com/${tenant}/oauth2/v2.0/authorize`;token=`https://login.microsoftonline.com/${tenant}/oauth2/v2.0/token`;scopes='openid offline_access User.Read';origin='https://graph.microsoft.com';method='post';note='Register a Web redirect URI for this server-side flow. Use your tenant ID for organization-specific apps.';}
 if(provider==='auth0'||provider==='okta'){if(!domain)throw Error('Enter your tenant HTTPS origin first.');const u=new URL(domain);if(u.protocol!=='https:'||u.pathname!=='/')throw Error('Use an HTTPS origin without a path.');auth=domain+(provider==='auth0'?'/authorize':'/oauth2/default/v1/authorize');token=domain+(provider==='auth0'?'/oauth/token':'/oauth2/default/v1/token');scopes='openid profile offline_access';note=provider==='auth0'?'Set audience in the extra parameters to your API identifier. Enable offline access and refresh tokens in Auth0.':'This preset uses the default custom authorization server. Adjust endpoints for your own server and enable refresh-token grants.';}
 if(provider==='github'){auth='https://github.com/login/oauth/authorize';token='https://github.com/login/oauth/access_token';origin='https://api.github.com';scopes='read:user';method='post';note='Standard GitHub OAuth App tokens generally do not include a refresh token. Expiring GitHub App user tokens can support refresh; use that app registration if needed.';}
 if(provider==='custom')note='Use your provider documentation. Supports Authorization Code + PKCE and Bearer tokens; not device-code, implicit, password, client-credentials, mTLS or DPoP flows.';
 $('oauth-authorization').value=auth;$('oauth-token').value=token;$('oauth-scopes').value=scopes;$('oauth-api-origin').value=origin;$('oauth-auth-method').value=method;$('oauth-extra').value=JSON.stringify(extra,null,2);$('oauth-provider-note').textContent=note;$('oauth-secret').value='';
}
async function api(action,data){const r=await fetch('/api/oauth/'+action,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.error||'OAuth request failed.');return d;}
async function status(){const r=await fetch('/api/oauth/status');const d=await r.json();signedIn=r.status!==401;$('oauth-signin').hidden=signedIn;$('oauth-connect').disabled=!r.ok;$('use-oauth').disabled=!d.connected;$('use-oauth').checked=!!d.connected;$('oauth-disconnect').disabled=!d.connected;$('oauth-refresh').disabled=!d.refreshAvailable;
 $('oauth-status').textContent=r.ok?(d.connected?`${d.provider} connected · ${d.apiOrigin} · ${d.refreshAvailable?'Automatic refresh available':'No refresh token — reconnect if access expires'}${d.expiresAt?' · Expires '+new Date(d.expiresAt).toLocaleString():''}`:'No API account connected yet.'):d.error;
}
const guard=fn=>async()=>{try{await fn();}catch(e){$('oauth-status').textContent=e.message;}};
$('oauth-preset').onclick=guard(preset);$('oauth-provider').onchange=guard(()=>{if(['google','microsoft','github','custom'].includes($('oauth-provider').value)){$('oauth-domain').value='';preset();}else {for(const id of ['oauth-authorization','oauth-token','oauth-scopes','oauth-api-origin','oauth-secret'])$(id).value='';$('oauth-provider-note').textContent='Enter your tenant HTTPS origin, then apply the preset.';}});
$('oauth-callback').value=location.origin+'/api/oauth/callback';preset();
$('oauth-connect').onclick=guard(async()=>{if(!signedIn)throw Error('Sign in to ReleaseRadar first.');const extra=JSON.parse($('oauth-extra').value||'{}');$('oauth-connect').disabled=true;try{const d=await api('start',{provider:$('oauth-provider').selectedOptions[0].textContent,authorizationUrl:$('oauth-authorization').value,tokenUrl:$('oauth-token').value,clientId:$('oauth-client').value,clientSecret:$('oauth-secret').value,scopes:$('oauth-scopes').value,apiOrigin:$('oauth-api-origin').value,authMethod:$('oauth-auth-method').value,extra});$('oauth-secret').value='';location.assign(d.authorizeUrl);}finally{$('oauth-connect').disabled=false;}});
$('oauth-refresh').onclick=guard(async()=>{await api('refresh',{});await status();});$('oauth-disconnect').onclick=guard(async()=>{await api('disconnect',{});await status();});status().catch(()=>{$('oauth-status').textContent='OAuth status unavailable. Retry after loading the hosted site.';});
